/** Parse a CON/END USSD screen from the FastAPI plain-text handler. */
function parseUssdResponse(raw) {
	const trimmed = raw.trimStart();
	if (trimmed.startsWith("END ")) return {
		kind: "END",
		body: trimmed.slice(4),
		raw
	};
	if (trimmed.startsWith("CON ")) return {
		kind: "CON",
		body: trimmed.slice(4),
		raw
	};
	return {
		kind: "END",
		body: trimmed,
		raw
	};
}
/** Invoke the live USSD webhook (same path Africa's Talking POSTs to). */
async function postUssd(params) {
	const body = new URLSearchParams({
		sessionId: params.sessionId,
		serviceCode: params.serviceCode,
		phoneNumber: params.phoneNumber,
		text: params.text
	});
	const res = await fetch(`${BASE_URL}${BASE_URL ? "/ussd" : "/api/ussd"}`, {
		method: "POST",
		headers: { "Content-Type": "application/x-www-form-urlencoded" },
		body: body.toString()
	});
	if (!res.ok) {
		const text = await res.text().catch(() => res.statusText);
		throw new Error(`SokoSense USSD ${res.status}: ${text}`);
	}
	return parseUssdResponse(await res.text());
}
